sys_script_client.script:
// MSSCUSTODY-3414 - Created this Client Script to show/hide related list depending upon Bulk Task type
function onLoad() {


    var blkTskType = g_scratchpad.blkTskRelated;
    var getOutcome = g_form.getValue('outcome'); //MSSCUSTODY-8824
    var newDesignEnabled = g_scratchpad.newDesignEnabled;

    if (newDesignEnabled) { //hiding all the old tabs
        if (blkTskType == 'Maker') {
            g_form.hideRelatedList('REL:476307b21b6b4210971e6204b24bcbc0'); // Related list for All task
            g_form.hideRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
            g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
            g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for Pending Rejection
            g_form.hideRelatedList('REL:dc102e4d1ba7fad02ac120a8b04bcbe4'); //// pending rejection new design
            g_form.hideRelatedList('REL:506fd60d1ba7fad02ac120a8b04bcbdd'); //// pending rejection new design
        } else if (blkTskType == 'Checker') {
            g_form.showRelatedList('REL:dc102e4d1ba7fad02ac120a8b04bcbe4'); //// pending rejection new design
            g_form.showRelatedList('REL:506fd60d1ba7fad02ac120a8b04bcbdd'); //// pending rejection new design
            g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // pending rejection
            g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // pending approval
            g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
            g_form.hideRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
            g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for pending Rejection
            g_form.hideRelatedList('REL:476307b21b6b4210971e6204b24bcbc0'); // Related list for All task
            g_form.hideRelatedList('REL:639d74f11bc4b690cf016467b04bcbf5'); // Related list for All task historical
            //new list
        } else if (blkTskType == 'GHSS Handler') {
            g_form.hideRelatedList('REL:dc102e4d1ba7fad02ac120a8b04bcbe4'); //// pending rejection new design
            g_form.hideRelatedList('REL:506fd60d1ba7fad02ac120a8b04bcbdd'); //// pending rejection new design
            g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // pending rejection
            g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // pending approval
            g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
            g_form.hideRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
            g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for pending Rejection
            g_form.hideRelatedList('REL:476307b21b6b4210971e6204b24bcbc0'); // Related list for All task
            g_form.hideRelatedList('REL:639d74f11bc4b690cf016467b04bcbf5'); // Related list for All task historical
        }
    } else { //old logic retained
        //hiding all new related lists as part of redesign
        g_form.hideRelatedList('REL:dc102e4d1ba7fad02ac120a8b04bcbe4'); //// pending rejection new design
        g_form.hideRelatedList('REL:506fd60d1ba7fad02ac120a8b04bcbdd'); //// pending rejection new design
        g_form.hideRelatedList('REL:86222f0efb3a3ad0208cfd9aaeefdc7b'); // Trades new design
        g_form.hideRelatedList('REL:f068ff4bfbfaf214b181fbf7beefdcaf'); //Tasks new design
        //hiding all new related lists as part of redesign

        if (blkTskType === 'Maker') {
            g_form.showRelatedList('REL:476307b21b6b4210971e6204b24bcbc0'); // Related list for All task
            g_form.showRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
            g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
            g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for Pending Rejection

        } else if ((blkTskType === 'Checker') && (getOutcome != 'Review and closed the task')) {
            g_form.showRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
            g_form.showRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for pending Rejection
            g_form.showRelatedList('REL:476307b21b6b4210971e6204b24bcbc0'); // Related list for All task
            g_form.hideRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
        } else if ((blkTskType === 'GHSS Handler') || (getOutcome == 'Review and closed the task')) { //MSSCUSTODY-8824
            g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
            g_form.hideRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
            g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for pending Rejection
        }

    }
}
